st.components.v2.component(
    name="sidebar_user_toggle",
    js="""
    export default function() {
        const CLASS_NAME = "ocb-user-sidebar-hidden";
        const SIDEBAR_STYLE_ID = "ocb-user-sidebar-style";
        const BUTTON_STYLE_ID = "ocb-user-sidebar-toggle-style";
        const BUTTON_ID = "ocb-user-sidebar-toggle-button";

        const root = document.documentElement;


        // =========================================================
        // 1. STYLE ĐÓNG SIDEBAR
        // =========================================================
        if (!document.getElementById(SIDEBAR_STYLE_ID)) {
            const style = document.createElement("style");

            style.id = SIDEBAR_STYLE_ID;

            style.textContent = `
                html.${CLASS_NAME} [data-testid="stSidebar"] {
                    display: none !important;
                }

                html.${CLASS_NAME}
                [data-testid="stExpandSidebarButton"] {
                    display: none !important;
                }
            `;

            document.head.appendChild(style);
        }


        // =========================================================
        // 2. STYLE NÚT ⇆
        // =========================================================
        if (!document.getElementById(BUTTON_STYLE_ID)) {
            const style = document.createElement("style");

            style.id = BUTTON_STYLE_ID;

            style.textContent = `
                #${BUTTON_ID} {
                    all: unset !important;

                    position: fixed !important;

                    right: 5px !important;
                    bottom: 5px !important;

                    z-index: 100000 !important;

                    width: 30px !important;
                    height: 30px !important;

                    display: flex !important;
                    align-items: center !important;
                    justify-content: center !important;

                    box-sizing: border-box !important;

                    font-family: inherit !important;
                    font-size: 26px !important;
                    font-weight: 400 !important;
                    line-height: 1 !important;

                    color: inherit !important;

                    background: transparent !important;
                    border: none !important;
                    box-shadow: none !important;

                    opacity: 0.42;

                    cursor: pointer !important;
                    user-select: none !important;

                    transition:
                        opacity 0.15s ease,
                        transform 0.15s ease !important;
                }


                #${BUTTON_ID}:hover {
                    opacity: 0.9;
                    transform: scale(1.08);
                }


                #${BUTTON_ID}:active {
                    opacity: 1;
                    transform: scale(0.94);
                }


                #${BUTTON_ID}:focus {
                    outline: none !important;
                    box-shadow: none !important;
                }
            `;

            document.head.appendChild(style);
        }


        // =========================================================
        // 3. TẠO NÚT NẾU CHƯA CÓ
        // =========================================================
        let button = document.getElementById(BUTTON_ID);

        if (!button) {
            button = document.createElement("button");

            button.id = BUTTON_ID;
            button.type = "button";
            button.textContent = "⇆";

            document.body.appendChild(button);
        }


        // =========================================================
        // 4. TITLE + ACCESSIBILITY
        // =========================================================
        const updateButtonState = () => {
            const sidebarHidden =
                root.classList.contains(CLASS_NAME);

            const label = sidebarHidden
                ? "Mở sidebar"
                : "Đóng sidebar";

            button.title = label;
            button.setAttribute("aria-label", label);
        };


        // =========================================================
        // 5. USER TOGGLE
        // =========================================================
        button.onclick = () => {
            root.classList.toggle(CLASS_NAME);

            updateButtonState();
        };


        updateButtonState();
    }
    """
)

st.components.v2.component(
    name="sidebar_toggle_ocb",
    js="""
    export default function() {
        // Đảm bảo event listener chỉ được gắn 1 lần duy nhất trong suốt vòng đời của app
        if (!window.__sidebar_toggle_listener) {
            document.addEventListener('keydown', (event) => {
                // Bỏ qua nếu người dùng đang nhập văn bản
                const activeTag = document.activeElement ? document.activeElement.tagName : '';
                if (['INPUT', 'TEXTAREA'].includes(activeTag)) return;

                // Bắt tổ hợp phím Ctrl + Space
                if (event.ctrlKey && (event.code === 'Space' || event.key === ' ')) {
                    event.preventDefault(); // Ngăn hành vi cuộn trang mặc định của phím Space

                    const sidebar = document.querySelector('[data-testid="stSidebar"]');
                    const isExpanded = sidebar ? sidebar.getAttribute('aria-expanded') === 'true' : false;

                    if (isExpanded) {
                        // NẾU ĐANG MỞ -> Bấm nút đóng bên trong sidebar
                        const closeBtn = sidebar.querySelector('button');
                        if (closeBtn) closeBtn.click();
                    } else {
                        // NẾU ĐANG ĐÓNG -> Bấm nút mở (Expand Button) của Streamlit
                        const openBtn = document.querySelector('[data-testid="stExpandSidebarButton"]');
                        if (openBtn) openBtn.click();
                    }
                }
            });
            window.__sidebar_toggle_listener = true;
        }
    }
    """
)

st.components.v2.component(
    name="sidebar_close_ocb",
    js="""
    export default function() {
        const CLASS_NAME = "ocb-local-sidebar-hidden";
        const STYLE_ID = "ocb-local-sidebar-style";

        // Chỉ inject CSS một lần trong tab hiện tại
        if (!document.getElementById(STYLE_ID)) {
            const style = document.createElement("style");
            style.id = STYLE_ID;
            style.textContent = `
                html.${CLASS_NAME} [data-testid="stSidebar"] {
                    display: none !important;
                }

                html.${CLASS_NAME} [data-testid="stExpandSidebarButton"] {
                    display: none !important;
                }
            `;
            document.head.appendChild(style);
        }

        // Chỉ tác động DOM của browser tab hiện tại
        document.documentElement.classList.add(CLASS_NAME);

        // Nếu component thật sự bị unmount trong chính tab này,
        // trả sidebar về trạng thái hiển thị bình thường.
        return () => {
            document.documentElement.classList.remove(CLASS_NAME);
        };
    }
    """
)

