st.components.v2.component(
    name="keyboard_shortcuts_ocb",
    js="""
    export default function(component) {
        // LIÊN TỤC CẬP NHẬT hàm gửi dữ liệu mới nhất vào bộ nhớ trình duyệt
        window.__setTrigger_OCB = component.setTriggerValue;

        // Chỉ gắn ống nghe bàn phím 1 lần duy nhất
        if (!window.__kb_listener_ocb) {
            document.addEventListener('keydown', (event) => {
                if (event.altKey) {
                    const key = event.key.toLowerCase();
                    // Gọi qua hàm __setTrigger_OCB mới nhất
                    if (key === 'n' && window.__setTrigger_OCB) {
                        window.__setTrigger_OCB("action", "next_" + Date.now());
                    } else if (key === 'p' && window.__setTrigger_OCB) {
                        window.__setTrigger_OCB("action", "prev_" + Date.now());
                    }
                }
            });
            window.__kb_listener_ocb = true;
        }
    }
    """
)

st.components.v2.component(
    name="google_translator_injector",
    js="""
    export default function() {
        if (!window.parent.__translator_injected) {
            const parentDoc = window.parent.document;
            const parentWin = window.parent;

            // 1. Container cho nút dịch
            const container = parentDoc.createElement('div');
            container.id = 'google_translate_element';
            container.style.position = 'fixed';
            container.style.top = '15px';
            container.style.right = '15px';
            container.style.zIndex = '9999999';
            parentDoc.body.appendChild(container);

            // 2. CSS để thu gọn tối đa và ẩn các thành phần thừa
            const style = parentDoc.createElement('style');
            style.innerHTML = `
                /* Ẩn toàn bộ văn bản trong nút bấm chính */
                .goog-te-gadget-simple span { display: none !important; }
                /* Chỉ cho phép hiển thị hình ảnh (Logo Google) */
                .goog-te-gadget-simple img { display: inline-block !important; margin: 0 !important; }
                /* Làm sạch khung nút */
                .goog-te-gadget-simple {
                    background-color: transparent !important;
                    border: none !important;
                    padding: 0 !important;
                }
                /* Ẩn widget của Google khi đã dịch xong (thanh ngang trên cùng) */
                .goog-te-banner-frame { display: none !important; }
                body { top: 0 !important; }
            `;
            parentDoc.head.appendChild(style);

            // 3. Khởi tạo và Dùng MutationObserver để xóa chữ "cứng đầu"
            parentWin.googleTranslateElementInit = function() {
                new parentWin.google.translate.TranslateElement({
                    pageLanguage: 'en',
                    includedLanguages: 'vi',
                    layout: parentWin.google.translate.TranslateElement.InlineLayout.SIMPLE
                }, 'google_translate_element');

                // Quan sát sự thay đổi của DOM để xóa text ngay khi nó được render
                const observer = new MutationObserver(() => {
                    // Xóa chữ ở nút bấm chính
                    const menuValue = parentDoc.querySelector('.goog-te-menu-value');
                    if (menuValue) {
                        // Giữ lại logo, xóa tất cả text node
                        Array.from(menuValue.childNodes).forEach(node => {
                            if (node.nodeType === Node.TEXT_NODE || (node.tagName && node.tagName !== 'IMG')) {
                                node.textContent = '';
                                if(node.style) node.style.display = 'none';
                            }
                        });
                    }

                    // Xóa dòng "Chọn ngôn ngữ" trong menu thả xuống (iframe)
                    const iframe = parentDoc.querySelector('.goog-te-menu-frame');
                    if (iframe) {
                        const innerDoc = iframe.contentDocument || iframe.contentWindow.document;
                        const header = innerDoc.querySelector('.goog-te-menu2-header');
                        if (header) {
                            header.style.display = 'none';
                            innerDoc.body.style.paddingTop = '0';
                        }
                    }
                });

                observer.observe(parentDoc.body, { childList: true, subtree: true });
            };

            const script = parentDoc.createElement('script');
            script.type = 'text/javascript';
            script.src = 'https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';
            parentDoc.head.appendChild(script);

            window.parent.__translator_injected = true;
        }
    }
    """
)

