                else if (event.code === 'Space' || event.key === ' ') {
                    event.preventDefault(); // Ngăn trình duyệt cuộn dọc
                    if (window.__setTrigger_OCB) {
                        window.__setTrigger_OCB("action", "btn_show_" + Date.now());
                    }
                }
            });
            window.__kb_listener_ocb = true;
        }
    }
    """
