st.components.v2.component(
    name="scapp_anki_reviewer_keyboard_shortcuts",
    js=r"""
    export default function(component) {
        window.__scappAnkiReviewerTrigger = component.setTriggerValue;

        if (!window.__scappAnkiReviewerKeyboardListener) {
            document.addEventListener('keydown', (event) => {
                const active = document.activeElement;
                const tag = active && active.tagName ? active.tagName.toUpperCase() : '';
                const isEditable = Boolean(
                    active && (
                        active.isContentEditable ||
                        ['INPUT', 'TEXTAREA', 'SELECT'].includes(tag)
                    )
                );
                if (isEditable) return;

                let action = '';
                if (event.code === 'Space' || event.key === ' ') {
                    action = 'toggle_answer';
                } else if (event.code === 'Digit1' || event.code === 'Numpad1' || event.key === '1') {
                    action = 'rating_again';
                } else if (event.code === 'Digit2' || event.code === 'Numpad2' || event.key === '2') {
                    action = 'rating_hard';
                } else if (event.code === 'Digit3' || event.code === 'Numpad3' || event.key === '3') {
                    action = 'rating_good';
                } else if (event.code === 'Digit4' || event.code === 'Numpad4' || event.key === '4') {
                    action = 'rating_easy';
                }

                if (!action) return;
                event.preventDefault();
                if (window.__scappAnkiReviewerTrigger) {
                    window.__scappAnkiReviewerTrigger(
                        'action',
                        action + '_' + Date.now()
                    );
                }
            });
            window.__scappAnkiReviewerKeyboardListener = true;
        }
    }
    """,
)

